  const ctx=new Context(),lookup=new PluginPackages(ctx);f.dispose(()=>ctx.fiber.dispose());const adapters={environment:{prepare:(pwd,opts)=>prepareProfilePackageBackup(pwd,{profiles:()=>({home:f.home,installAnchor:anchor,active:{name:profile,dir,cwd:f.project,startedBundles:[name],overlays:[]}}),packages:()=>({lookup,seeds:[{key:'EXAMPLE',name,parentURL:pathToFileURL(join(dir,'package.json')).href,scope:'declared',directory:pkg}],protectedContainers:[f.root],forbiddenTrees:[]})},opts),restore:async(file,pwd,target,opts)=>summarizeEnvironment(await restoreProfilePackageBackup(file,pwd,target,{...opts,installAnchor:anchor}))},skills:{prepare:(_pwd,opts)=>prepareSkillInventoryBackup(()=>f.source,opts),restore:async(...args)=>summarizeSkills(await restoreSkillInventoryBackup(...args))}};
  if(sessions){const active=new Context();f.dispose(()=>active.fiber.dispose());await active.plugin(Sessions);await active.plugin(Jsonl,{root:join(f.home,'EXAMPLE_SESSIONS')});await active.plugin(Attachments,{dshHome:f.home});await active.plugin(Query,{path:':memory:',openAt:'never'});const handle=await active.sessionPersistence.create({id:SessionId('EXAMPLE_PROJECT_SESSION'),version:SESSION_FORMAT_VERSION,createdAt:1700000000000,cwd:f.cwd,isSeeded:false});try{await handle.flush();}finally{await handle.close();}adapters.sessions={prepare:(_pwd,opts)=>prepareSessionBackup(()=>({sessions:active.sessions,sessionPersistence:active.sessionPersistence,sessionQuery:active.sessionQuery,attachments:active.attachments}),opts),restore:async(...args)=>summarizeSessions(await restoreSessionBackup(...args))};}
